import re, os, subprocess, json
from playwright.sync_api import sync_playwright
OUT='tests/acct50'; os.makedirs(OUT, exist_ok=True)
subprocess.run(['python3','tests/smoke40.py','/home/claude/site/index.html',OUT], capture_output=True)
html=open(f'{OUT}/smoke.html').read()
html=re.sub(r'<script src="https://cdn.jsdelivr.net/npm/@supabase[^"]*"></script>', '<script>'+open('tests/sbmock.js').read().replace('</script','<\\/script')+'</script>', html)
open(f'{OUT}/acct.html','w').write(html)
p=sync_playwright().start(); b=p.chromium.launch()
errs=[]
def newpage():
    pg=b.new_page(viewport={"width":1380,"height":900}); pg.on("pageerror", lambda e: errs.append(str(e))); pg.on("console", lambda m: errs.append("console: "+m.text) if m.type=="error" else None); return pg
pg=newpage(); pg.goto(f"file://{OUT}/acct.html"); pg.wait_for_timeout(900)
print("1 auth screen:", pg.get_by_role("button", name=re.compile("^Sign in$")).count())
# create owner account
pg.get_by_role("button", name=re.compile("Create an account")).click(); pg.wait_for_timeout(200)
pg.locator('input[placeholder^="Your name"]').fill("Dalton"); pg.locator('input[type="email"]').fill("owner@test.com"); pg.locator('input[type="password"]').fill("password123")
pg.get_by_role("button", name=re.compile("^Create account$")).click(); pg.wait_for_timeout(400)
print("2 signup msg:", pg.locator("text=check your email").count())
pg.locator('input[type="email"]').fill("owner@test.com"); pg.locator('input[type="password"]').fill("password123"); pg.get_by_role("button", name=re.compile("^Sign in$")).click(); pg.wait_for_timeout(900)
pg.get_by_role("button", name=re.compile("Enter payroll")).click(); pg.wait_for_timeout(500)
print("3 owner in app:", pg.locator("aside.ss-side").count(), "| footer:", pg.locator("aside .ss-side-user").inner_text().replace("\n"," | "))
# add a chatter + shift so chatters have data
pg.locator('section input').first.fill("Zuna"); pg.wait_for_timeout(100)
pg.locator('section select').first.select_option("Team Spicy"); pg.wait_for_timeout(100)
pg.get_by_role("button", name=re.compile(r"\+ Add shift")).click(); pg.wait_for_timeout(200)
pg.locator('input[placeholder="8"]').first.fill("8"); pg.locator('input[placeholder="0.00"]').first.fill("1300"); pg.locator('table.ss-shifts input[type="date"]').first.fill("2026-11-02"); pg.wait_for_timeout(1200)
print("4 sync log:", pg.evaluate("window.__sb.log"), "| status:", pg.locator("aside .ss-side-meta").first.inner_text().split("\n")[-1])
pg.locator("aside.ss-side button[title='Settings']").click(); pg.wait_for_timeout(400)
print("5 people section:", pg.locator("#set-people").count(), "| nav has People:", pg.locator("a[href='#set-people']").count())
pg.locator("aside.ss-side button[title='Payroll']").click(); pg.wait_for_timeout(200)
pg.evaluate("""() => { const id='u_chatter'; window.__sb.users['zuna@test.com']={id, email:'zuna@test.com', password:'password123', name:'Zuna'}; window.__sb.db.profiles[id]={id, email:'zuna@test.com', display_name:'Zuna', role:'pending', created_at:new Date().toISOString()}; }""")
pg.locator("aside.ss-side button[title='Settings']").click(); pg.wait_for_timeout(600)
print("6 pending listed:", pg.locator("#set-people").inner_text().count("Waiting for approval"), "| Approve btn:", pg.locator("#set-people button", has_text="Approve").count())
pg.locator("#set-people input[list]").first.fill("Zuna")
pg.locator("#set-people button", has_text="Approve").first.click(); pg.wait_for_timeout(500)
print("7 after approve role:", pg.evaluate("window.__sb.db.profiles['u_chatter'].role"), pg.evaluate("window.__sb.db.profiles['u_chatter'].chatter_name"))
# now sign out, sign in as chatter → limited app
pg.locator("aside .ss-side-user button").click(); pg.wait_for_timeout(500)
pg.locator('input[type="email"]').fill("zuna@test.com"); pg.locator('input[type="password"]').fill("password123"); pg.get_by_role("button", name=re.compile("^Sign in$")).click(); pg.wait_for_timeout(900)
print("8 chatter view:", pg.locator("text=Earnings statement").count(), "| gross:", pg.locator("text=Gross pay").count(), "| aside hidden:", pg.locator("aside.ss-side").count()==0)
pg.screenshot(path=f"{OUT}/chatter.png")
pg.get_by_role("button", name=re.compile("^Leaderboard$")).click(); pg.wait_for_timeout(300)
print("9 board rows:", pg.locator("main li").count(), "| me marked:", pg.locator("text=(you)").count())
# manager: sign out, make a manager, try changing pay rate → should be refused
pg.get_by_role("button", name=re.compile("Sign out")).click(); pg.wait_for_timeout(400)
pg.evaluate("""() => { const id='u_mgr'; window.__sb.users['leagin@test.com']={id, email:'leagin@test.com', password:'password123', name:'Leagin'}; window.__sb.db.profiles[id]={id, email:'leagin@test.com', display_name:'Leagin', role:'manager', created_at:new Date().toISOString()}; }""")
pg.locator('input[type="email"]').fill("leagin@test.com"); pg.locator('input[type="password"]').fill("password123"); pg.get_by_role("button", name=re.compile("^Sign in$")).click(); pg.wait_for_timeout(900)
pg.get_by_role("button", name=re.compile("Enter payroll")).click(); pg.wait_for_timeout(500)
pg.locator("aside.ss-side button[title='Settings']").click(); pg.wait_for_timeout(500)
print("10 manager settings sections:", pg.locator("#set-rates").count(), pg.locator("#set-goals").count(), pg.locator("#set-people").count())
# manager edits pay period (allowed)
pg.locator("aside.ss-side button[title='Payroll']").click(); pg.wait_for_timeout(300)
pg.locator('input[placeholder^="e.g. Oct"]').fill("Nov 2 – 8"); pg.wait_for_timeout(1200)
print("11 manager allowed write:", pg.evaluate("window.__sb.db.app_state.main.data.settings.payPeriod"), "| status:", pg.locator("aside .ss-side-meta").first.inner_text().split("\n")[-1])
# external newer state → applied
pg.evaluate("""() => { const d=JSON.parse(JSON.stringify(window.__sb.db.app_state.main.data)); d.employees[0].name='Zuna-iPhone'; window.__sb.externalState(d); }""")
pg.wait_for_timeout(800)
print("12 external applied:", pg.locator('section input').first.input_value())
print("errors:", [e[:160] for e in errs[:4]])
b.close(); p.stop()
